(function(){
  const store=window.HostelStore;
  const root=document.getElementById('pageRoot');
  const modalRoot=document.getElementById('modalRoot');
  const titles={dashboard:'Dashboard',students:'Student management',rooms:'Room management',allocation:'Smart allocation',records:'Allocation records',reports:'Reports',settings:'Settings'};
  let charts=[];
  const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const all=key=>store.read(key);
  const activeAllocations=()=>all('allocations').filter(item=>item.status==='Active');
  const countForRoom=roomId=>activeAllocations().filter(item=>item.roomId===roomId).length;
  const studentById=id=>all('students').find(item=>item.id===id);
  const roomById=id=>all('rooms').find(item=>item.id===id);
  const dateText=value=>value?new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'—';
  const timeText=value=>value?new Date(value).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'—';
  const initials=name=>String(name||'').split(/\s+/).slice(0,2).map(part=>part[0]||'').join('').toUpperCase();
  const roomLabel=room=>room?`${room.hostel} · ${room.roomNumber}`:'Room unavailable';
  const roomTypeOptions=['Single Sharing','Double Sharing','Triple Sharing','Four Sharing'];
  function icon(name){return `<i data-lucide="${name}"></i>`;}
  function refreshIcons(){if(window.lucide)window.lucide.createIcons();}
  function stats(){const students=all('students'),rooms=all('rooms'),allocs=activeAllocations();const capacity=rooms.reduce((sum,room)=>sum+Number(room.capacity||0),0);const occupied=allocs.length;const pending=all('suggestions').filter(item=>item.status==='Pending').length;return{students:students.length,rooms:rooms.length,capacity,occupied,available:Math.max(capacity-occupied,0),pending};}
  function updateNav(){const counts=stats();document.getElementById('studentNavCount').textContent=counts.students||'';document.getElementById('pendingNavCount').textContent=counts.pending||'';}
  function pageHeader(eyebrow,title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`;}
  function statCard(label,value,foot,iconName,color){return `<article class="stat-card"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon ${color}">${icon(iconName)}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></article>`;}
  function statusBadge(status){const styles={Active:'active',Approved:'approved',Allocated:'allocated',Pending:'pending',Rejected:'rejected',Cancelled:'cancelled',Available:'available',Full:'full'};return `<span class="status status-${styles[status]||'pending'}">${esc(status)}</span>`;}
  function cardEmpty(title,message,iconName='inbox'){return `<div class="empty-state">${icon(iconName)}<strong>${title}</strong><p>${message}</p></div>`;}
  function tableEmpty(columns,title,message){return `<tr><td colspan="${columns}">${cardEmpty(title,message)}</td></tr>`;}
  function actionButton(action,id,label,iconName,extra=''){return `<button class="icon-button" data-action="${action}" data-id="${esc(id)}" title="${esc(label)}" aria-label="${esc(label)}" ${extra}>${icon(iconName)}</button>`;}
  function tablePanel(content){return `<section class="panel"><div class="table-wrap">${content}</div></section>`;}
  function render(){
    const page=(location.hash.slice(1)||'dashboard');
    const selected=titles[page]?page:'dashboard';
    document.getElementById('pageTitle').textContent=titles[selected];
    document.querySelectorAll('[data-nav]').forEach(link=>link.classList.toggle('active',link.dataset.nav===selected));
    document.getElementById('todayLabel').textContent=new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'});
    charts.forEach(chart=>chart.destroy());charts=[];
    root.innerHTML=({dashboard:renderDashboard,students:renderStudents,rooms:renderRooms,allocation:renderAllocation,records:renderRecords,reports:renderReports,settings:renderSettings}[selected])();
    updateNav();refreshIcons();
    if(selected==='dashboard')drawDashboardChart();
    if(selected==='reports')drawReportsCharts();
  }
  function renderDashboard(){
    const s=stats();const rooms=all('rooms');const suggestions=all('suggestions').filter(item=>item.status==='Pending');const logs=all('activityLogs').slice(0,4);const recent=all('students').slice().sort((a,b)=>b.applicationDate.localeCompare(a.applicationDate)).slice(0,4);
    const hour=new Date().getHours(),greeting=`Good ${hour<12?'morning':hour<17?'afternoon':'evening'}, Admin`;
    const roomRows=rooms.slice(0,5).map(room=>{const occupied=countForRoom(room.id),percent=room.capacity?Math.round(occupied/room.capacity*100):0;return `<div class="occupancy-row"><span class="occupancy-name">${esc(room.hostel)} / ${esc(room.roomNumber)}</span><div class="progress-track"><div class="progress-fill ${percent>=85?'high':''}" style="width:${percent}%"></div></div><span class="occupancy-value">${occupied}/${room.capacity} beds</span></div>`;}).join('');
    const activity=logs.map(item=>`<div class="activity-item"><span class="activity-mark">${icon(item.type==='allocation'?'badge-check':item.type==='recommendation'?'sparkles':'activity')}</span><div class="activity-copy">${esc(item.message)}<small>${timeText(item.createdAt)}</small></div></div>`).join('')||cardEmpty('Nothing yet','Activity will appear here as you manage the hostel.');
    const studentRows=recent.map(student=>`<div class="activity-item"><span class="student-avatar">${esc(initials(student.name))}</span><div class="activity-copy"><strong>${esc(student.name)}</strong><small>${esc(student.department)} · Applied ${dateText(student.applicationDate)}</small></div>${statusBadge(student.status==='Allocated'?'Allocated':'Pending')}</div>`).join('')||cardEmpty('No students yet','New registrations will show up here.','users-round');
    const pendingCards=suggestions.slice(0,2).map(suggestion=>{const student=studentById(suggestion.studentId),room=roomById(suggestion.roomId);return `<div class="activity-item"><span class="activity-mark">${icon('sparkles')}</span><div class="activity-copy"><strong>${esc(student?.name||'Student')}</strong><small>${esc(roomLabel(room))} · ${suggestion.score}% match</small></div><a class="panel-link" href="#allocation">Review</a></div>`;}).join('')||`<div class="notice">No recommendations waiting for approval.</div>`;
    return `${pageHeader('HOSTEL OVERVIEW',greeting,'Here is what is happening across your hostel today.',`<button class="btn btn-secondary" data-action="export-csv">${icon('download')} Export report</button><button class="btn btn-primary" data-action="quick-student">${icon('user-plus')} Add student</button>`)}
      <section class="stat-grid">${statCard('Total students',s.students,'Registered in the system','users-round','blue')}${statCard('Total rooms',s.rooms,'Across all hostels','door-open','cyan')}${statCard('Bed capacity',s.capacity,'Total available beds','bed-double','amber')}${statCard('Occupied beds',s.occupied,`${s.capacity?Math.round(s.occupied/s.capacity*100):0}% of total capacity`,'badge-check','green')}${statCard('Available beds',s.available,'Ready for allocation','bed','blue')}${statCard('Pending approvals',s.pending,'Awaiting your review','clock-3','amber')}</section>
      <div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Room occupancy</h2><p>Current bed usage by room</p></div><a href="#rooms" class="panel-link">All rooms ${icon('arrow-up-right')}</a></div><div class="panel-body"><div class="occupancy-list">${roomRows||cardEmpty('No rooms configured','Add rooms to see occupancy data.','door-open')}</div></div></section>
        <section class="panel"><div class="panel-head"><div><h2>Bed availability</h2><p>Occupied versus available beds</p></div></div><div class="panel-body"><div class="chart-wrap"><canvas id="dashboardChart" aria-label="Occupied and available beds chart"></canvas></div><div class="chart-legend"><span><i class="legend-dot"></i>Occupied (${s.occupied})</span><span><i class="legend-dot orange"></i>Available (${s.available})</span></div></div></section></div>
      <div class="lower-grid"><section class="panel"><div class="panel-head"><div><h2>Recent registrations</h2><p>Latest student applications</p></div><a href="#students" class="panel-link">View students ${icon('arrow-up-right')}</a></div><div class="panel-body"><div class="activity-list">${studentRows}</div></div></section>
      <section class="panel"><div class="panel-head"><div><h2>Needs your attention</h2><p>Pending allocation recommendations</p></div><a href="#allocation" class="panel-link">Review all ${icon('arrow-up-right')}</a></div><div class="panel-body"><div class="activity-list">${pendingCards}</div><div class="quick-actions"><button class="quick-action" data-action="quick-room"><span class="qa-icon">${icon('door-open')}</span><span><strong>Add a room</strong><small>Expand capacity</small></span></button><button class="quick-action" data-action="generate"><span class="qa-icon">${icon('sparkles')}</span><span><strong>Find matches</strong><small>Generate suggestions</small></span></button><a class="quick-action" href="#reports"><span class="qa-icon">${icon('chart-no-axes-column-increasing')}</span><span><strong>View reports</strong><small>Check occupancy</small></span></a></div></div></section></div>
      <section class="panel" style="margin-top:15px"><div class="panel-head"><div><h2>Recent activity</h2><p>Latest changes made in this workspace</p></div><a href="#records" class="panel-link">Allocation records ${icon('arrow-up-right')}</a></div><div class="panel-body"><div class="activity-list">${activity}</div></div></section>`;
  }
  function renderStudents(){
    const students=all('students'),departments=[...new Set(students.map(item=>item.department))].sort(),years=[...new Set(students.map(item=>item.year))].sort();
    const actions=`<button class="btn btn-primary" data-action="add-student">${icon('user-plus')} Add student</button>`;
    return `${pageHeader('PEOPLE','Student management','Maintain student applications and allocation preferences.',actions)}<div class="toolbar"><div class="search-wrap">${icon('search')}<input class="input" id="studentSearch" placeholder="Search name, ID, email..." aria-label="Search students"></div><select class="select" id="studentDepartment"><option value="">All departments</option>${departments.map(value=>`<option>${esc(value)}</option>`).join('')}</select><select class="select" id="studentYear"><option value="">All years</option>${years.map(value=>`<option>${esc(value)}</option>`).join('')}</select><select class="select" id="studentGender"><option value="">All genders</option><option>Male</option><option>Female</option></select></div>${tablePanel(`<table class="data-table"><thead><tr><th>Student</th><th>Department / year</th><th>Gender</th><th>Preference</th><th>Applied</th><th>Status</th><th>Actions</th></tr></thead><tbody id="studentRows">${studentRows(students)}</tbody></table>`)}`;
  }
  function studentRows(students){if(!students.length)return tableEmpty(7,'No students found','Try changing your search or filters.');return students.map(student=>`<tr><td><div class="primary-cell"><span class="student-avatar">${esc(initials(student.name))}</span><span><strong>${esc(student.name)}</strong><small>${esc(student.studentId)}</small></span></div></td><td>${esc(student.department)}<small style="display:block;color:#929eac;margin-top:3px">${esc(student.year)}</small></td><td>${esc(student.gender)}</td><td>${esc(student.hostel)}<small style="display:block;color:#929eac;margin-top:3px">${esc(student.roomType)}</small></td><td>${dateText(student.applicationDate)}</td><td>${statusBadge(student.status==='Allocated'?'Allocated':'Pending')}</td><td><div class="row-actions">${actionButton('view-student',student.id,'View details','eye')}${actionButton('edit-student',student.id,'Edit student','pencil')}${actionButton('delete-student',student.id,'Delete student','trash-2')}</div></td></tr>`).join('');}
  function renderRooms(){
    const rooms=all('rooms'),hostels=[...new Set(rooms.map(item=>item.hostel))].sort(),counts={male:0,female:0,guest:0};rooms.forEach(room=>counts[roomCategory(room)]++);const actions=`<button class="btn btn-primary" data-action="add-room">${icon('plus')} Add room</button>`;
    const categories=[{key:'male',label:'Male'},{key:'female',label:'Female'},{key:'guest',label:'Guest'}];
    const categoryOptions=categories.map((category,index)=>`<button type="button" class="room-category-button${index===0?' active':''}" data-room-category="${category.key}" aria-pressed="${index===0}"><span>${category.label}</span><b>${counts[category.key]}</b></button>`).join('');
    const rows=roomTableRows(rooms.filter(room=>roomCategory(room)==='male'));
    return `${pageHeader('PROPERTY','Room management','Manage room inventory, eligibility and bed capacity.',actions)}<section class="room-category-box" aria-label="Room eligibility categories"><div class="room-category-heading"><span>ROOM CATEGORIES</span><strong>Browse rooms by eligibility</strong></div><div class="room-category-options" id="roomCategoryFilters" role="group" aria-label="Filter rooms by eligibility">${categoryOptions}</div></section><div class="toolbar"><div class="search-wrap">${icon('search')}<input class="input" id="roomSearch" placeholder="Search room, number..." aria-label="Search rooms"></div><select class="select" id="roomHostel"><option value="">All hostels</option>${hostels.map(value=>`<option>${esc(value)}</option>`).join('')}</select><select class="select" id="roomTypeFilter"><option value="">All room types</option>${roomTypeOptions.map(value=>`<option>${esc(value)}</option>`).join('')}</select><select class="select" id="roomAvailability"><option value="">Any availability</option><option value="available">Available</option><option value="full">Full</option></select></div>${tablePanel(`<table class="data-table"><thead><tr><th>Room</th><th>Hostel / floor</th><th>Type</th><th>Eligibility</th><th>Occupancy</th><th>Status</th><th>Actions</th></tr></thead><tbody id="roomRows">${rows}</tbody></table>`)}`;
  }
  function roomCategory(room){return room.gender==='Male'?'male':room.gender==='Female'?'female':'guest';}
  function roomTableRows(rooms){if(!rooms.length)return tableEmpty(7,'No rooms found','Try changing your search or filters.');return rooms.map(room=>{const occupied=countForRoom(room.id),available=Math.max(room.capacity-occupied,0);return `<tr><td><div class="primary-cell"><span class="stat-icon cyan">${icon('door-open')}</span><span><strong>${esc(room.roomId)}</strong><small>Room ${esc(room.roomNumber)}</small></span></div></td><td>${esc(room.hostel)}<small style="display:block;color:#929eac;margin-top:3px">Floor ${esc(room.floor)}</small></td><td>${esc(room.type)}</td><td>${esc(room.gender)}</td><td>${occupied} / ${room.capacity}<small style="display:block;color:#929eac;margin-top:3px">${available} available</small></td><td>${statusBadge(available?'Available':'Full')}</td><td><div class="row-actions">${actionButton('edit-room',room.id,'Edit room','pencil')}${actionButton('delete-room',room.id,'Delete room','trash-2')}</div></td></tr>`;}).join('');}
  function roomEligible(student,room){return room.gender===student.gender&&(student.hostel==='Any'||student.hostel===room.hostel)&&countForRoom(room.id)<Number(room.capacity);}
  function renderAllocation(){
    const suggestions=all('suggestions').filter(item=>item.status==='Pending').sort((a,b)=>b.score-a.score);const s=stats();
    const cards=suggestions.map(item=>{const student=studentById(item.studentId),room=roomById(item.roomId);if(!student||!room)return '';return `<article class="recommendation-card"><div class="recommendation-main"><div class="recommendation-student"><span class="student-avatar">${esc(initials(student.name))}</span><div><h3>${esc(student.name)}</h3><p>${esc(student.studentId)} · ${esc(student.department)}</p></div></div><div class="recommendation-details"><span>${icon('door-open')} ${esc(room.hostel)} · Room ${esc(room.roomNumber)}</span><span>${icon('bed-double')} ${esc(student.roomType)} preference</span><span>${icon('calendar-days')} Applied ${dateText(student.applicationDate)}</span></div><div class="recommendation-details"><span>${icon('check')} ${esc(item.reasons.join(' · '))}</span></div><div class="recommendation-actions"><button class="btn btn-primary btn-small" data-action="approve" data-id="${esc(item.id)}">${icon('check')} Approve</button><button class="btn btn-secondary btn-small" data-action="reject" data-id="${esc(item.id)}">${icon('x')} Reject</button></div></div><div class="score-block"><div class="score-ring" style="--score:${item.score}"><span>${item.score}%</span></div><small>MATCH SCORE</small></div></article>`;}).join('');
    const actions=`<button class="btn btn-secondary" data-action="allocation-help">${icon('info')} How matching works</button><button class="btn btn-primary" data-action="generate">${icon('sparkles')} Generate recommendations</button>`;
    return `${pageHeader('ASSISTED PLACEMENT','Smart allocation','Review room matches, then approve or reject each recommendation.',actions)}<div class="summary-grid">${statCard('Unallocated students',all('students').filter(st=>st.status!=='Allocated').length,'Eligible for matching','users-round','blue')}${statCard('Rooms with space',all('rooms').filter(room=>countForRoom(room.id)<room.capacity).length,'Capacity checked live','door-open','cyan')}${statCard('Pending review',s.pending,'No beds are reserved','clock-3','amber')}${statCard('Available beds',s.available,'Across all hostels','bed','green')}</div><div class="notice" style="margin-bottom:13px">Recommendations are suggestions only. A bed is assigned only after you approve, and availability is checked again at that moment.</div><div class="allocation-list">${cards||`<section class="panel">${cardEmpty('No recommendations to review','Generate recommendations for students without an active allocation.','sparkles')}</section>`}</div>`;
  }
  function renderRecords(){
    const rows=recordRows(all('suggestions'),all('allocations'));const rooms=all('rooms');
    return `${pageHeader('HISTORY','Allocation records','Review recommendation outcomes and manage active placements.',`<button class="btn btn-secondary" data-action="export-csv">${icon('download')} Export CSV</button>`)}<div class="toolbar"><div class="search-wrap">${icon('search')}<input class="input" id="recordSearch" placeholder="Search student name or ID..." aria-label="Search records"></div><select class="select" id="recordHostel"><option value="">All hostels</option>${[...new Set(rooms.map(r=>r.hostel))].map(h=>`<option>${esc(h)}</option>`).join('')}</select><select class="select" id="recordStatus"><option value="">All statuses</option><option>Active</option><option>Pending</option><option>Rejected</option><option>Cancelled</option></select></div>${tablePanel(`<table class="data-table"><thead><tr><th>Student</th><th>Room</th><th>Record type</th><th>Status</th><th>Date</th><th>Notes</th><th>Action</th></tr></thead><tbody id="recordRows">${rows}</tbody></table>`)}`;
  }
  function recordRows(suggestions,allocations){
    const records=[...allocations.map(item=>({...item,kind:'allocation'})),...suggestions.map(item=>({...item,kind:'suggestion'}))].sort((a,b)=>new Date(b.approvedAt||b.cancelledAt||b.createdAt)-new Date(a.approvedAt||a.cancelledAt||a.createdAt));
    if(!records.length)return tableEmpty(7,'No allocation history','Recommendations and approved assignments will appear here.');
    return records.map(item=>{const student=studentById(item.studentId),room=roomById(item.roomId);const status=item.kind==='allocation'?(item.status==='Active'?'Active':'Cancelled'):item.status;const date=item.approvedAt||item.cancelledAt||item.createdAt;return `<tr data-record-status="${esc(status)}" data-record-hostel="${esc(room?.hostel||'')}" data-record-text="${esc(`${student?.name||''} ${student?.studentId||''}`.toLowerCase())}"><td><div class="primary-cell"><span class="student-avatar">${esc(initials(student?.name||'NA'))}</span><span><strong>${esc(student?.name||'Student record')}</strong><small>${esc(student?.studentId||'Student removed')}</small></span></div></td><td>${esc(roomLabel(room))}</td><td>${item.kind==='allocation'?'Approved allocation':'Recommendation'}</td><td>${statusBadge(status==='Active'?'Approved':status)}</td><td>${dateText(date)}</td><td>${esc(item.reason||item.rejectionReason||`${item.score??'—'}% match`)}</td><td>${item.kind==='allocation'&&item.status==='Active'?`<button class="btn btn-danger btn-small" data-action="cancel-allocation" data-id="${esc(item.id)}">${icon('undo-2')} Cancel</button>`:'—'}</td></tr>`;}).join('');
  }
  function renderReports(){
    const s=stats(),rooms=all('rooms'),suggestions=all('suggestions');const approved=activeAllocations().length,pending=suggestions.filter(item=>item.status==='Pending').length,rejected=suggestions.filter(item=>item.status==='Rejected').length;const hostels=[...new Set(rooms.map(room=>room.hostel))];
    const roomTiles=rooms.map(room=>{const occupied=countForRoom(room.id),percent=room.capacity?Math.round(occupied/room.capacity*100):0;return `<div class="room-tile"><strong>${esc(room.hostel)} · ${esc(room.roomNumber)}</strong><small>${esc(room.type)} · ${occupied}/${room.capacity} beds · ${percent}%</small><div class="progress-track"><div class="progress-fill ${percent>=85?'high':''}" style="width:${percent}%"></div></div></div>`;}).join('')||'<div class="notice">No rooms available for reporting.</div>';
    return `${pageHeader('INSIGHTS','Reports','A live summary of student placements and room utilization.',`<button class="btn btn-secondary" data-action="export-csv">${icon('download')} Export CSV</button><button class="btn btn-primary" data-action="print-report">${icon('printer')} Print report</button>`)}<div class="summary-grid">${statCard('Students',s.students,'All registered students','users-round','blue')}${statCard('Rooms',s.rooms,'Configured room inventory','door-open','cyan')}${statCard('Bed capacity',s.capacity,'Total room capacity','bed-double','amber')}${statCard('Occupied beds',s.occupied,`${s.available} beds available`,'badge-check','green')}</div><div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Hostel occupancy</h2><p>Occupied beds by hostel</p></div></div><div class="panel-body"><div class="chart-wrap"><canvas id="hostelChart" aria-label="Hostel occupancy chart"></canvas></div></div></section><section class="panel"><div class="panel-head"><div><h2>Allocation outcomes</h2><p>Current approved and pending records</p></div></div><div class="panel-body"><div class="chart-wrap"><canvas id="outcomeChart" aria-label="Allocation outcomes chart"></canvas></div><div class="chart-legend"><span><i class="legend-dot"></i>Approved (${approved})</span><span><i class="legend-dot orange"></i>Pending (${pending})</span><span><i class="legend-dot" style="background:#b8c2d0"></i>Rejected (${rejected})</span></div></div></section></div><section class="panel" style="margin-top:14px"><div class="panel-head"><div><h2>Room-wise occupancy</h2><p>${s.capacity?Math.round(s.occupied/s.capacity*100):0}% overall utilization · ${s.occupied} of ${s.capacity} beds occupied</p></div></div><div class="panel-body"><div class="room-tiles">${roomTiles}</div></div></section>`;
  }
  function renderSettings(){const settings=all('settings'),weights=settings.weights||{roomType:40,hostel:30,availability:20,priority:10};return `${pageHeader('WORKSPACE','Settings','Configure matching preferences and manage your local data.')}<div class="settings-layout"><section class="panel settings-section"><h2>Hostel configuration</h2><p>Keep this list aligned with the hostels used in student preferences and room records.</p><form id="hostelSettingsForm"><div class="field"><label for="hostelList">Hostel names, separated by commas</label><textarea class="textarea" id="hostelList" name="hostels" required>${esc((settings.hostels||[]).join(', '))}</textarea></div><div style="margin-top:11px;text-align:right"><button class="btn btn-primary">${icon('save')} Save hostels</button></div></form><div class="settings-row"><span><strong>Room types</strong><small>Supported room categories</small></span></div><div class="notice">${roomTypeOptions.join(' · ')}</div></section><section class="panel settings-section"><h2>Recommendation scoring</h2><p>Weights are normalized into a match percentage. Eligibility and available capacity remain mandatory.</p><form id="weightsForm">${[['roomType','Room type preference'],['hostel','Hostel preference'],['availability','Availability suitability'],['priority','Application priority']].map(([key,label])=>`<div class="settings-row"><span><strong>${label}</strong><small>Scoring weight</small></span><input class="input" type="number" min="0" max="100" name="${key}" value="${Number(weights[key]??0)}" required></div>`).join('')}<div style="text-align:right;margin-top:12px"><button class="btn btn-primary">${icon('save')} Save scoring</button></div></form></section><section class="panel settings-section"><h2>Application data</h2><p>All records are stored in this browser using localStorage. Export a backup before moving browsers or devices.</p><div class="settings-row"><span><strong>Download backup</strong><small>Export all data as a JSON file</small></span><button class="btn btn-secondary btn-small" data-action="backup">${icon('download')} Export JSON</button></div><div class="settings-row"><span><strong>Restore backup</strong><small>Replace current data from a valid JSON backup</small></span><label for="restoreFile" class="btn btn-secondary btn-small">${icon('upload')} Choose file</label><input id="restoreFile" class="file-input" type="file" accept="application/json,.json"></div><div class="settings-row"><span><strong>Reset demonstration data</strong><small>Replace local records with the original sample data</small></span><button class="btn btn-danger btn-small" data-action="reset-data">${icon('rotate-ccw')} Reset data</button></div></section><section class="panel settings-section"><h2>About Haven</h2><p>Smart Hostel Room Allocation System · Admin workspace</p><div class="settings-row"><span><strong>Application</strong><small>Client-side hostel management</small></span><span class="status status-available">Local storage</span></div><div class="settings-row"><span><strong>Data keys</strong><small>Students, rooms, allocations, suggestions, settings, activity logs</small></span></div><div class="notice warning">This browser does not synchronize data with other devices. Store regular backups in a secure location.</div></section></div>`;}
  function createChart(canvasId,config){const canvas=document.getElementById(canvasId);if(!canvas||!window.Chart)return;charts.push(new Chart(canvas,config));}
  function drawDashboardChart(){const s=stats();createChart('dashboardChart',{type:'doughnut',data:{labels:['Occupied','Available'],datasets:[{data:[s.occupied,s.available],backgroundColor:['#2563eb','#f2ad50'],borderWidth:0,hoverOffset:4}]},options:{responsive:true,maintainAspectRatio:false,cutout:'72%',plugins:{legend:{display:false},tooltip:{enabled:true}}}});}
  function drawReportsCharts(){const rooms=all('rooms'),hostels=[...new Set(rooms.map(room=>room.hostel))],suggestions=all('suggestions');createChart('hostelChart',{type:'bar',data:{labels:hostels,datasets:[{label:'Occupied',data:hostels.map(hostel=>rooms.filter(room=>room.hostel===hostel).reduce((sum,room)=>sum+countForRoom(room.id),0)),backgroundColor:'#2563eb',borderRadius:4},{label:'Available',data:hostels.map(hostel=>rooms.filter(room=>room.hostel===hostel).reduce((sum,room)=>sum+Math.max(room.capacity-countForRoom(room.id),0),0)),backgroundColor:'#f2ad50',borderRadius:4}]},options:{responsive:true,maintainAspectRatio:false,scales:{x:{grid:{display:false}},y:{beginAtZero:true,ticks:{precision:0},grid:{color:'#edf1f5'}}},plugins:{legend:{position:'bottom',labels:{boxWidth:8,usePointStyle:true,font:{size:10}}}}}});createChart('outcomeChart',{type:'doughnut',data:{labels:['Approved','Pending','Rejected'],datasets:[{data:[activeAllocations().length,suggestions.filter(item=>item.status==='Pending').length,suggestions.filter(item=>item.status==='Rejected').length],backgroundColor:['#2563eb','#f2ad50','#b8c2d0'],borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,cutout:'66%',plugins:{legend:{position:'bottom',labels:{boxWidth:8,usePointStyle:true,font:{size:10}}}}}});}
  function openModal(title,subtitle,body,buttons=''){modalRoot.innerHTML=`<div class="modal-backdrop" data-action="backdrop-close"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div><button class="icon-button" data-action="close-modal" aria-label="Close">${icon('x')}</button></div><div class="modal-body">${body}</div>${buttons?`<div class="modal-foot">${buttons}</div>`:''}</section></div>`;refreshIcons();modalRoot.querySelector('input,select,textarea')?.focus();}
  function closeModal(){modalRoot.innerHTML='';}
  function field(label,name,value='',type='text',required=true,options=null,placeholder=''){let control;if(options){control=`<select class="select" name="${name}" ${required?'required':''}>${options.map(option=>`<option value="${esc(option.value)}" ${String(option.value)===String(value)?'selected':''}>${esc(option.label)}</option>`).join('')}</select>`;}else control=`<input class="input" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0"':''} placeholder="${esc(placeholder)}">`;return `<div class="field"><label>${label}${required?' <span class="required">*</span>':''}</label>${control}</div>`;}
  function openStudentForm(student=null){const editing=Boolean(student),hostels=all('settings').hostels||[];const hostelOptions=[{value:'Any',label:'Any hostel'},...hostels.map(item=>({value:item,label:item}))];const body=`<form id="studentForm" data-id="${esc(student?.id||'')}"><div class="form-grid">${field('Student ID','studentId',student?.studentId||'')}${field('Full name','name',student?.name||'')}${field('Gender','gender',student?.gender||'Male','text',true,['Male','Female'].map(value=>({value,label:value})))}${field('Department','department',student?.department||'')}${field('Academic year','year',student?.year||'1st Year','text',true,['1st Year','2nd Year','3rd Year','4th Year','Other'].map(value=>({value,label:value})))}${field('Contact number','phone',student?.phone||'','tel')}${field('Email address','email',student?.email||'','email')}${field('Preferred hostel','hostel',student?.hostel||hostelOptions[0]?.value||'Any','text',true,hostelOptions)}${field('Preferred room type','roomType',student?.roomType||'Double Sharing','text',true,roomTypeOptions.map(value=>({value,label:value})))}${field('Application date','applicationDate',student?.applicationDate||new Date().toISOString().slice(0,10),'date')}</div></form>`;openModal(editing?'Edit student':'Add student','Student details are managed by the hostel administrator.',body,`<button class="btn btn-secondary" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="submit-student">${icon('save')} ${editing?'Save changes':'Add student'}</button>`);}
  function openRoomForm(room=null){const editing=Boolean(room),hostels=all('settings').hostels||[];const options=hostels.map(item=>({value:item,label:item}));const eligibility=['Male','Female','Staff / Guest only'].map(value=>({value,label:value}));const body=`<form id="roomForm" data-id="${esc(room?.id||'')}"><div class="form-grid">${field('Room ID','roomId',room?.roomId||'')}${field('Room number','roomNumber',room?.roomNumber||'')}${field('Hostel block','hostel',room?.hostel||options[0]?.value||'','text',true,options)}${field('Floor number','floor',room?.floor??1,'number')}${field('Room type','type',room?.type||'Double Sharing','text',true,roomTypeOptions.map(value=>({value,label:value})))}${field('Gender eligibility','gender',room?.gender||'Male','text',true,eligibility)}${field('Total bed capacity','capacity',room?.capacity??2,'number')}</div><p class="field-hint" style="margin-top:10px">Occupied: ${room?countForRoom(room.id):0} · Available beds update automatically from active allocations.</p></form>`;openModal(editing?'Edit room':'Add room','Set room details and who is eligible to stay.',body,`<button class="btn btn-secondary" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="submit-room">${icon('save')} ${editing?'Save changes':'Add room'}</button>`);}
  function toast(message,type='success'){const el=document.createElement('div');el.className=`toast ${type==='error'?'error':''}`;el.innerHTML=`${icon(type==='error'?'circle-alert':'circle-check')}<span>${esc(message)}</span>`;document.getElementById('toastRoot').appendChild(el);refreshIcons();setTimeout(()=>el.remove(),3500);}
  function showStudent(id){const student=studentById(id);if(!student)return;const body=`<div class="form-grid">${[['Student ID',student.studentId],['Full name',student.name],['Gender',student.gender],['Department',student.department],['Academic year',student.year],['Contact',student.phone],['Email',student.email],['Hostel preference',student.hostel],['Room type',student.roomType],['Applied',dateText(student.applicationDate)],['Allocation status',student.status]].map(([label,value])=>`<div class="field"><label>${label}</label><div>${esc(value||'—')}</div></div>`).join('')}</div>`;openModal(student.name,'Student application details',body,`<button class="btn btn-secondary" data-action="close-modal">Close</button><button class="btn btn-primary" data-action="edit-student" data-id="${esc(id)}">${icon('pencil')} Edit student</button>`);}
  function scoreRoom(student,room,priority){const weights=all('settings').weights||{roomType:40,hostel:30,availability:20,priority:10};const total=Object.values(weights).reduce((sum,value)=>sum+Number(value||0),0)||1;const free=room.capacity-countForRoom(room.id);const parts={roomType:student.roomType===room.type?Number(weights.roomType):0,hostel:student.hostel==='Any'||student.hostel===room.hostel?Number(weights.hostel):0,availability:Number(weights.availability)*Math.min(1,free/Math.max(1,room.capacity)),priority:Number(weights.priority)*priority/10};const score=Math.round(Object.values(parts).reduce((sum,value)=>sum+value,0)/total*100);const reasons=[];if(student.roomType===room.type)reasons.push('Room type preference matches');if(student.hostel==='Any'||student.hostel===room.hostel)reasons.push('Preferred hostel matches');reasons.push(`${free} bed${free===1?'':'s'} currently available`);if(priority>=7)reasons.push('Earlier application date');return{score,reasons};}
  function generateRecommendations(){const students=all('students'),rooms=all('rooms'),suggestions=all('suggestions');const pendingStudentIds=new Set(suggestions.filter(item=>item.status==='Pending').map(item=>item.studentId));const candidates=students.filter(student=>student.status!=='Allocated'&&!activeAllocations().some(allocation=>allocation.studentId===student.id)&&!pendingStudentIds.has(student.id));if(!candidates.length){toast('No new unallocated students need recommendations.','error');return;}
    const dates=candidates.map(student=>new Date(student.applicationDate).getTime()||Date.now()),oldest=Math.min(...dates),newest=Math.max(...dates),range=Math.max(newest-oldest,86400000);let made=0,unmatched=0;
    candidates.sort((a,b)=>a.applicationDate.localeCompare(b.applicationDate)).forEach(student=>{const priority=10-((new Date(student.applicationDate).getTime()-oldest)/range*10);const eligible=rooms.filter(room=>roomEligible(student,room));if(!eligible.length){unmatched++;return;}const ranked=eligible.map(room=>({room,...scoreRoom(student,room,priority)})).sort((a,b)=>b.score-a.score||a.room.roomNumber.localeCompare(b.room.roomNumber));const best=ranked[0];suggestions.push({id:store.uid('sug'),studentId:student.id,roomId:best.room.id,score:best.score,reasons:best.reasons,status:'Pending',createdAt:new Date().toISOString()});store.log(`Recommendation generated for ${student.name}`,'recommendation');made++;});store.write('suggestions',suggestions);render();if(made)toast(`${made} recommendation${made===1?'':'s'} generated for administrator review.`);else toast(`${unmatched} student${unmatched===1?' has':'s have'} no eligible room with capacity.`,'error');}
  function approveSuggestion(id){const suggestions=all('suggestions'),suggestion=suggestions.find(item=>item.id===id);if(!suggestion||suggestion.status!=='Pending'){toast('This recommendation is no longer pending.','error');render();return;}const student=studentById(suggestion.studentId),room=roomById(suggestion.roomId);if(!student||student.status==='Allocated'||activeAllocations().some(item=>item.studentId===student.id)){toast('Student already has an active allocation.','error');return;}if(!room||!roomEligible(student,room)){toast('Room eligibility or capacity changed. Generate a fresh recommendation.','error');return;}if(!confirm(`Approve ${student.name} for ${room.hostel}, room ${room.roomNumber}?`))return;const allocations=all('allocations');allocations.push({id:store.uid('alloc'),studentId:student.id,roomId:room.id,status:'Active',approvedAt:new Date().toISOString()});store.write('allocations',allocations);suggestion.status='Approved';suggestion.approvedAt=new Date().toISOString();store.write('suggestions',suggestions);const students=all('students'),updated=students.find(item=>item.id===student.id);updated.status='Allocated';store.write('students',students);store.log(`Allocation approved for ${student.name}`,'allocation');render();toast('Allocation approved and recorded.');}
  function rejectSuggestion(id){const suggestions=all('suggestions'),suggestion=suggestions.find(item=>item.id===id);if(!suggestion||suggestion.status!=='Pending'){toast('This recommendation is no longer pending.','error');return;}const student=studentById(suggestion.studentId);if(!confirm(`Reject the recommendation for ${student?.name||'this student'}?`))return;const reason=prompt('Optional rejection reason:','');suggestion.status='Rejected';suggestion.rejectionReason=(reason||'').trim();suggestion.rejectedAt=new Date().toISOString();store.write('suggestions',suggestions);store.log(`Recommendation rejected for ${student?.name||'student'}`,'update');render();toast('Recommendation rejected. Student remains eligible.');}
  function cancelAllocation(id){const allocations=all('allocations'),allocation=allocations.find(item=>item.id===id);if(!allocation||allocation.status!=='Active'){toast('This allocation has already been cancelled.','error');return;}const student=studentById(allocation.studentId);if(!confirm(`Cancel the active allocation for ${student?.name||'this student'}? The bed will be released.`))return;allocation.status='Cancelled';allocation.cancelledAt=new Date().toISOString();store.write('allocations',allocations);const students=all('students');const record=students.find(item=>item.id===allocation.studentId);if(record)record.status='Pending';store.write('students',students);store.log(`Allocation cancelled for ${student?.name||'student'}`,'update');render();toast('Allocation cancelled and bed released.');}
  function formValues(form){return Object.fromEntries(new FormData(form).entries());}
  function submitStudent(){const form=document.getElementById('studentForm');if(!form.reportValidity())return;const data=formValues(form),students=all('students'),existing=students.find(item=>item.studentId.toLowerCase()===data.studentId.trim().toLowerCase()&&item.id!==form.dataset.id);if(existing){toast('That student ID is already in use.','error');return;}if(!/^\+?[0-9\s()-]{7,20}$/.test(data.phone)){toast('Enter a valid contact number.','error');return;}if(form.dataset.id){const student=students.find(item=>item.id===form.dataset.id);Object.assign(student,data);store.log(`Student details updated for ${student.name}`);}else{students.unshift({id:store.uid('stu'),...data,status:'Pending'});store.log(`Student added: ${data.name}`);}store.write('students',students);closeModal();render();toast(form.dataset.id?'Student details updated.':'Student added.');}
  function submitRoom(){const form=document.getElementById('roomForm');if(!form.reportValidity())return;const data=formValues(form),rooms=all('rooms'),id=form.dataset.id;data.floor=Number(data.floor);data.capacity=Number(data.capacity);if(!Number.isInteger(data.capacity)||data.capacity<1){toast('Capacity must be at least one bed.','error');return;}if(rooms.some(room=>room.roomId.toLowerCase()===data.roomId.trim().toLowerCase()&&room.id!==id)){toast('That room ID is already in use.','error');return;}if(rooms.some(room=>room.hostel===data.hostel&&room.roomNumber===data.roomNumber&&room.id!==id)){toast('That room number already exists in this hostel.','error');return;}if(id){const room=rooms.find(item=>item.id===id),occupied=countForRoom(id);if(data.capacity<occupied){toast(`Capacity cannot be below ${occupied} occupied bed${occupied===1?'':'s'}.`,'error');return;}Object.assign(room,data);store.log(`Room updated: ${room.hostel} ${room.roomNumber}`);}else{rooms.push({id:store.uid('room'),...data});store.log(`Room added: ${data.hostel} ${data.roomNumber}`);}store.write('rooms',rooms);closeModal();render();toast(id?'Room updated.':'Room added.');}
  function deleteStudent(id){const student=studentById(id);if(!student)return;if(activeAllocations().some(item=>item.studentId===id)){toast('Cancel this student’s active allocation before deleting the record.','error');return;}if(!confirm(`Delete student ${student.name}? This cannot be undone.`))return;store.write('students',all('students').filter(item=>item.id!==id));store.write('suggestions',all('suggestions').filter(item=>item.studentId!==id));store.log(`Student deleted: ${student.name}`);render();toast('Student deleted.');}
  function deleteRoom(id){const room=roomById(id);if(!room)return;if(activeAllocations().some(item=>item.roomId===id)){toast('Rooms with active allocations cannot be deleted.','error');return;}if(!confirm(`Delete room ${room.hostel}, ${room.roomNumber}?`))return;store.write('rooms',all('rooms').filter(item=>item.id!==id));store.write('suggestions',all('suggestions').filter(item=>item.roomId!==id||item.status!=='Pending'));store.log(`Room deleted: ${room.hostel} ${room.roomNumber}`);render();toast('Room deleted.');}
  function filterStudents(){const query=(document.getElementById('studentSearch')?.value||'').toLowerCase(),department=document.getElementById('studentDepartment')?.value||'',year=document.getElementById('studentYear')?.value||'',gender=document.getElementById('studentGender')?.value||'';const filtered=all('students').filter(student=>`${student.name} ${student.studentId} ${student.email}`.toLowerCase().includes(query)&&(!department||student.department===department)&&(!year||student.year===year)&&(!gender||student.gender===gender));const target=document.getElementById('studentRows');if(target)target.innerHTML=studentRows(filtered);refreshIcons();}
  function filterRooms(){const query=(document.getElementById('roomSearch')?.value||'').toLowerCase(),hostel=document.getElementById('roomHostel')?.value||'',type=document.getElementById('roomTypeFilter')?.value||'',availability=document.getElementById('roomAvailability')?.value||'',category=document.querySelector('#roomCategoryFilters [aria-pressed="true"]')?.dataset.roomCategory||'male';const filtered=all('rooms').filter(room=>roomCategory(room)===category&&`${room.roomId} ${room.roomNumber} ${room.hostel}`.toLowerCase().includes(query)&&(!hostel||room.hostel===hostel)&&(!type||room.type===type)&&(!availability||(availability==='available'?countForRoom(room.id)<room.capacity:countForRoom(room.id)>=room.capacity)));document.getElementById('roomRows').innerHTML=roomTableRows(filtered);refreshIcons();}
  function filterRecords(){const query=(document.getElementById('recordSearch')?.value||'').toLowerCase(),hostel=document.getElementById('recordHostel')?.value||'',status=document.getElementById('recordStatus')?.value||'';document.querySelectorAll('#recordRows tr[data-record-status]').forEach(row=>{row.hidden=!(row.dataset.recordText.includes(query)&&(!hostel||row.dataset.recordHostel===hostel)&&(!status||row.dataset.recordStatus===status));});}
  function exportCsv(){const records=[['Student ID','Student name','Department','Hostel','Room','Record type','Status','Date','Notes']];all('allocations').forEach(item=>{const student=studentById(item.studentId),room=roomById(item.roomId);records.push([student?.studentId,student?.name,student?.department,room?.hostel,room?.roomNumber,'Allocation',item.status,item.approvedAt||item.cancelledAt,'']);});all('suggestions').forEach(item=>{const student=studentById(item.studentId),room=roomById(item.roomId);records.push([student?.studentId,student?.name,student?.department,room?.hostel,room?.roomNumber,'Recommendation',item.status,item.createdAt,item.rejectionReason||`${item.score}% match`]);});const csv=records.map(row=>row.map(value=>`"${String(value??'').replace(/"/g,'""')}"`).join(',')).join('\r\n');downloadFile(`haven-report-${new Date().toISOString().slice(0,10)}.csv`,csv,'text/csv;charset=utf-8');toast('CSV report exported.');}
  function downloadFile(filename,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function exportBackup(){const data=Object.fromEntries(store.keys.map(key=>[key,all(key)]));downloadFile(`haven-backup-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(data,null,2),'application/json');toast('JSON backup exported.');}
  function validateBackup(data){if(!data||!['students','rooms','allocations','suggestions','settings','activityLogs'].every(key=>Array.isArray(data[key])||key==='settings'&&data.settings&&typeof data.settings==='object'))return 'Backup is missing required data collections.';const studentIds=new Set(data.students.map(item=>item.id)),roomIds=new Set(data.rooms.map(item=>item.id)),activeStudentIds=new Set();for(const allocation of data.allocations){if(!studentIds.has(allocation.studentId)||!roomIds.has(allocation.roomId))return 'An allocation references a missing student or room.';if(allocation.status==='Active'){if(activeStudentIds.has(allocation.studentId))return 'A student has more than one active allocation.';activeStudentIds.add(allocation.studentId);}}for(const room of data.rooms){const occupied=data.allocations.filter(item=>item.roomId===room.id&&item.status==='Active').length;if(Number(room.capacity)<occupied)return `Room ${room.roomNumber} capacity is lower than its active allocations.`;}const seen=new Set();for(const student of data.students){const key=String(student.studentId||'').toLowerCase();if(seen.has(key))return 'The backup contains duplicate student IDs.';seen.add(key);}return '';}
  async function restoreBackup(file){if(!file)return;try{const data=JSON.parse(await file.text()),error=validateBackup(data);if(error){toast(error,'error');return;}if(!confirm('Restore this backup? Current data in this browser will be replaced.'))return;store.keys.forEach(key=>store.write(key,data[key]));render();toast('Backup restored successfully.');}catch(error){toast('Could not read that backup file.','error');}finally{const input=document.getElementById('restoreFile');if(input)input.value='';}}
  function saveSettings(form,type){const settings=all('settings');if(type==='hostels'){const hostels=[...new Set(formValues(form).hostels.split(',').map(item=>item.trim()).filter(Boolean))];if(!hostels.length){toast('Add at least one hostel name.','error');return;}settings.hostels=hostels;}else{const values=formValues(form),weights=Object.fromEntries(Object.entries(values).map(([key,value])=>[key,Number(value)]));if(Object.values(weights).some(value=>!Number.isFinite(value)||value<0)||Object.values(weights).reduce((sum,value)=>sum+value,0)===0){toast('Scoring weights must be non-negative and their total must be greater than zero.','error');return;}settings.weights=weights;}store.write('settings',settings);store.log(type==='hostels'?'Hostel configuration updated':'Allocation scoring weights updated');render();toast('Settings saved.');}
  function resetData(){if(!confirm('Permanently replace all current browser data with demonstration data? Export a backup first if you need to keep it.'))return;store.keys.forEach(key=>store.write(key,structuredClone(store.defaults[key])));render();toast('Demonstration data restored.');}
  function handleAction(action,id){switch(action){case'toggle-menu':document.getElementById('sidebar').classList.toggle('open');break;case'close-modal':closeModal();break;case'backdrop-close':if(event.target.classList.contains('modal-backdrop'))closeModal();break;case'add-student':case'quick-student':openStudentForm();break;case'edit-student':{const student=studentById(id);if(student)openStudentForm(student);break;}case'view-student':showStudent(id);break;case'delete-student':deleteStudent(id);break;case'add-room':case'quick-room':openRoomForm();break;case'edit-room':{const room=roomById(id);if(room)openRoomForm(room);break;}case'delete-room':deleteRoom(id);break;case'submit-student':submitStudent();break;case'submit-room':submitRoom();break;case'generate':generateRecommendations();break;case'approve':approveSuggestion(id);break;case'reject':rejectSuggestion(id);break;case'cancel-allocation':cancelAllocation(id);break;case'export-csv':exportCsv();break;case'backup':exportBackup();break;case'reset-data':resetData();break;case'print-report':window.print();break;case'submit-hostels':saveSettings(document.getElementById('hostelSettingsForm'),'hostels');break;case'submit-weights':saveSettings(document.getElementById('weightsForm'),'weights');break;case'allocation-help':openModal('How matching works','Eligibility comes before scoring.',`<div class="notice">A student is considered only when they have no active allocation. The room must have a free bed and its gender eligibility and hostel preference must match. Eligible rooms are then ranked using the configured room type, hostel, availability and application-priority weights. Generating suggestions does not reserve a bed; approval rechecks all constraints.</div><div class="settings-row"><span><strong>Room type preference</strong><small>Preference match score</small></span><span>40 weight (default)</span></div><div class="settings-row"><span><strong>Hostel preference</strong><small>Preference match score</small></span><span>30 weight (default)</span></div><div class="settings-row"><span><strong>Availability / priority</strong><small>Capacity suitability and application date</small></span><span>20 / 10 (default)</span></div>`,`<button class="btn btn-primary" data-action="close-modal">Got it</button>`);break;case'show-shortcuts':openModal('Haven admin workspace','Local browser application',`<div class="notice">Manage students, room inventory, recommendations and allocation history from the navigation. All changes are saved in this browser. Use Settings to export or restore a JSON backup.</div>`,`<button class="btn btn-primary" data-action="close-modal">Close</button>`);break;}}
  document.addEventListener('click',event=>{const categoryButton=event.target.closest('[data-room-category]');if(categoryButton){document.querySelectorAll('[data-room-category]').forEach(button=>{const selected=button===categoryButton;button.classList.toggle('active',selected);button.setAttribute('aria-pressed',String(selected));});filterRooms();return;}const button=event.target.closest('[data-action]');if(!button)return;handleAction(button.dataset.action,button.dataset.id);});
  document.addEventListener('submit',event=>{if(event.target.id==='studentForm'){event.preventDefault();submitStudent();}else if(event.target.id==='roomForm'){event.preventDefault();submitRoom();}else if(event.target.id==='hostelSettingsForm'){event.preventDefault();saveSettings(event.target,'hostels');}else if(event.target.id==='weightsForm'){event.preventDefault();saveSettings(event.target,'weights');}});
  document.addEventListener('input',event=>{if(event.target.id==='studentSearch')filterStudents();if(event.target.id==='roomSearch')filterRooms();if(event.target.id==='recordSearch')filterRecords();});
  document.addEventListener('change',event=>{if(['studentDepartment','studentYear','studentGender'].includes(event.target.id))filterStudents();if(['roomHostel','roomTypeFilter','roomAvailability'].includes(event.target.id))filterRooms();if(['recordHostel','recordStatus'].includes(event.target.id))filterRecords();if(event.target.id==='restoreFile')restoreBackup(event.target.files[0]);});
  document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal();});
  window.addEventListener('hashchange',()=>{document.getElementById('sidebar').classList.remove('open');render();});
  render();
})();